-- IDEMPOTENTE. Rodar no Supabase SQL Editor. Não altera títulos (nada de remap).

begin;
update licoes set titulo = 'Passado simples — regulares', sub = 'worked, played, lived', explicacao = 'Verbos regulares no passado adicionam ''-ed'': work → worked, play → played. Igual para todas as pessoas.', dica = 'Verbos terminados em -e só adicionam -d: live → lived. Em consoante+y: study → studied.', exemplos = $j$[{"en":"I worked late yesterday.","pt":"Trabalhei até tarde ontem."},{"en":"She studied all night.","pt":"Ela estudou a noite toda."},{"en":"We watched a movie.","pt":"Assistimos a um filme."}]$j$::jsonb, questoes = $j$[{"q":"Passado de 'work':","ans":0,"ctx":"","exp":"work → worked.","opts":["worked","workd","work","working"]},{"q":"Passado de 'live':","ans":0,"ctx":"","exp":"live → lived (só -d).","opts":["lived","livd","liveed","living"]},{"q":"Passado de 'study':","ans":0,"ctx":"","exp":"study → studied.","opts":["studied","studyed","studed","studying"]},{"q":"'They ___ football.'","ans":0,"ctx":"jogaram","exp":"play → played.","opts":["played","play","plaied","playing"]},{"q":"'I ___ TV last night.'","ans":0,"ctx":"","exp":"watch → watched.","opts":["watched","watch","watchd","watching"]},{"q":"O '-ed' serve para:","ans":0,"ctx":"","exp":"Passado regular.","opts":["Passado de verbos regulares","Futuro","Plural","Presente"]}]$j$::jsonb where id = 'f59282b9-eb05-42c3-95e3-a6385c420f55';
update licoes set titulo = 'Phrasal verbs separáveis II', sub = 'turn it off / turn off the light', explicacao = 'Muitos phrasal verbs são separáveis: o objeto pode vir no meio (turn the TV off) ou no fim (turn off the TV). Mas se o objeto for um PRONOME (it, them), ele OBRIGATORIAMENTE vem no meio: turn it off.', dica = 'Regra de ouro: pronome sempre no meio. ''Turn off it'' esta errado.', exemplos = $j$[{"en":"Please turn the light off.","pt":"Por favor apague a luz."},{"en":"I picked it up yesterday.","pt":"Peguei isso ontem."},{"en":"She threw the old letters away.","pt":"Ela jogou as cartas velhas fora."}]$j$::jsonb, questoes = $j$[{"q":"Com pronome, o correto é:","ans":0,"ctx":"","exp":"Pronome sempre no meio.","opts":["turn it off","turn off it","off turn it","it turn off"]},{"q":"Complete: Can you ___ (o casaco)?","ans":0,"ctx":"","exp":"take it off (pronome no meio).","opts":["take it off","take off it","off take it","take off"]},{"q":"Qual está errado?","ans":0,"ctx":"","exp":"'Pick up it' é inválido.","opts":["Pick up it","Pick it up","Pick up the box","Pick the box up"]},{"q":"'Throw away' com 'them':","ans":0,"ctx":"","exp":"Pronome no meio.","opts":["throw them away","throw away them","away throw them","them throw away"]},{"q":"Separável significa que:","ans":0,"ctx":"","exp":"Objeto pode ir no meio.","opts":["o objeto pode ir no meio","nunca se separa","não tem objeto","só usa gerúndio"]},{"q":"Com substantivo ambos servem, EXCETO:","ans":0,"ctx":"","exp":"Só o pronome quebra a regra.","opts":["Turn off it","Turn off the radio","Turn the radio off","Turn it off"]}]$j$::jsonb where id = '6db0c262-1339-49eb-a124-3da31f33c63b';
update licoes set titulo = 'Make x Do (avançado)', sub = 'make a decision / do research', explicacao = 'MAKE = criar, produzir, resultado (make a decision, make progress, make a mistake). DO = executar tarefa/atividade (do research, do the housework, do business). São colocações fixas que você memoriza.', dica = 'Dica: make = algo novo surge; do = uma ação/tarefa é realizada.', exemplos = $j$[{"en":"We need to make a decision today.","pt":"Precisamos tomar uma decisão hoje."},{"en":"She does research at the university.","pt":"Ela faz pesquisa na universidade."},{"en":"They made a lot of progress.","pt":"Eles fizeram muito progresso."}]$j$::jsonb, questoes = $j$[{"q":"Complete: ___ a decision","ans":0,"ctx":"","exp":"make a decision.","opts":["make","do","take","have"]},{"q":"Complete: ___ the housework","ans":0,"ctx":"","exp":"do the housework.","opts":["do","make","take","give"]},{"q":"Complete: ___ progress","ans":0,"ctx":"","exp":"make progress.","opts":["make","do","get","put"]},{"q":"Complete: ___ business with","ans":0,"ctx":"","exp":"do business.","opts":["do","make","take","have"]},{"q":"Complete: ___ a mistake","ans":0,"ctx":"","exp":"make a mistake.","opts":["make","do","have","get"]},{"q":"Complete: ___ someone a favour","ans":0,"ctx":"","exp":"do a favour.","opts":["do","make","give","take"]}]$j$::jsonb where id = 'a650955b-759f-44c5-8193-afab198f85c0';
update licoes set titulo = 'Inversão para ênfase III', sub = 'Never have I seen...', explicacao = 'Em inglês formal, ao começar a frase com advérbio negativo (never, rarely, seldom, not only, hardly), invertemos sujeito e verbo auxiliar: Never HAVE I seen such beauty.', dica = 'Depois do negativo inicial, use ordem de pergunta (auxiliar + sujeito).', exemplos = $j$[{"en":"Never have I seen such a mess.","pt":"Nunca vi tamanha bagunça."},{"en":"Rarely does he arrive late.","pt":"Raramente ele chega atrasado."},{"en":"Not only did she sing, she also danced.","pt":"Ela não só cantou, como também dançou."}]$j$::jsonb, questoes = $j$[{"q":"Complete: Never ___ such a thing.","ans":0,"ctx":"","exp":"Inversão após 'never'.","opts":["have I heard","I have heard","I heard have","heard I have"]},{"q":"Complete: Rarely ___ mistakes.","ans":0,"ctx":"","exp":"does + sujeito + verbo.","opts":["does she make","she makes","she does make","make she does"]},{"q":"'Not only... but also' pede:","ans":0,"ctx":"","exp":"Inversão após 'not only'.","opts":["inversão","ordem normal","gerúndio","passado simples"]},{"q":"A inversão soa:","ans":0,"ctx":"","exp":"Ênfase formal.","opts":["formal/enfática","informal","errada","infantil"]},{"q":"Complete: Hardly ___ when it rained.","ans":0,"ctx":"","exp":"Inversão após 'hardly'.","opts":["had we arrived","we had arrived","we arrived had","arrived we had"]},{"q":"Qual está correto?","ans":0,"ctx":"","exp":"do + I + verbo.","opts":["Seldom do I complain.","Seldom I complain.","Seldom I do complain.","Seldom complain I."]}]$j$::jsonb where id = 'fda81d6d-43c2-46e2-ad99-1637d4bcbdc9';
update licoes set titulo = 'Cleft sentences II', sub = 'What I need is time', explicacao = 'Frases clivadas destacam uma informação. Comuns: ''It was X that...'' (It was John that called) e ''What... is/was'' (What I need is time). Servem para dar ênfase a uma parte da frase.', dica = 'Use ''What + oração + is'' para enfatizar o que importa.', exemplos = $j$[{"en":"What I need is more time.","pt":"O que eu preciso é mais tempo."},{"en":"It was Ana who solved it.","pt":"Foi a Ana que resolveu."},{"en":"What she wants is respect.","pt":"O que ela quer é respeito."}]$j$::jsonb, questoes = $j$[{"q":"Complete: ___ I want is peace.","ans":0,"ctx":"","exp":"What... is (clivada).","opts":["What","That","Which","Who"]},{"q":"Complete: It was John ___ called.","ans":0,"ctx":"","exp":"It was + pessoa + who.","opts":["who","which","what","whose"]},{"q":"Clivadas servem para:","ans":0,"ctx":"","exp":"Ênfase.","opts":["dar ênfase","fazer perguntas","negar","pedir"]},{"q":"Complete: ___ we did was leave.","ans":0,"ctx":"","exp":"All we did was...","opts":["All","Every","Much","Some"]},{"q":"Escolha a clivada:","ans":0,"ctx":"","exp":"Estrutura What... is.","opts":["What matters is honesty.","Honesty matters.","Is honesty matter.","Matter honesty is."]},{"q":"'It was in 2020 that...' enfatiza:","ans":0,"ctx":"","exp":"Ênfase no tempo.","opts":["o tempo (quando)","a pessoa","o objeto","o lugar"]}]$j$::jsonb where id = '7116f0e5-7522-4313-8c8f-212b43409329';
update licoes set titulo = 'Mixed conditionals III', sub = 'If I had studied, I would be...', explicacao = 'Condicionais mistas combinam tempos. Passado->presente: ''If I had studied (passado), I would be rich now (presente)''. Presente->passado: ''If I were rich (agora), I would have bought it (antes)''.', dica = 'Olhe o TEMPO de cada parte: a condição e o resultado podem estar em momentos diferentes.', exemplos = $j$[{"en":"If I had saved money, I would be free now.","pt":"Se eu tivesse economizado, estaria livre agora."},{"en":"If she were taller, she would have joined.","pt":"Se ela fosse mais alta, teria entrado."},{"en":"If he had slept, he wouldn't be tired.","pt":"Se ele tivesse dormido, não estaria cansado."}]$j$::jsonb, questoes = $j$[{"q":"Complete: If I had left earlier, I ___ here now.","ans":0,"ctx":"","exp":"Passado->presente: would be.","opts":["would be","would have been","will be","am"]},{"q":"Complete: If I were rich, I ___ that car.","ans":0,"ctx":"","exp":"Presente->passado: would have.","opts":["would have bought","would buy","will buy","bought"]},{"q":"Mixed conditional combina:","ans":0,"ctx":"","exp":"Tempos diferentes.","opts":["tempos diferentes","só o presente","só o futuro","só imperativo"]},{"q":"'If I had studied, I would be a doctor' fala de:","ans":0,"ctx":"","exp":"Passado -> presente.","opts":["passado afetando o presente","futuro","só passado","só presente"]},{"q":"Complete: If she spoke French, she ___ the job.","ans":0,"ctx":"","exp":"Presente habitual -> passado.","opts":["would have got","would get","will get","got"]},{"q":"A parte 'if' com 'had + particípio' é:","ans":0,"ctx":"","exp":"Passado irreal (3o cond.).","opts":["passado irreal","futuro","presente real","ordem"]}]$j$::jsonb where id = '994c5b5c-ab41-4e32-bbdc-cbb558808aef';
update licoes set titulo = 'Wish / If only II', sub = 'I wish I knew...', explicacao = 'Para lamentos: WISH + passado (arrependimento do presente): ''I wish I knew'' (queria saber). WISH + past perfect (arrependimento do passado): ''I wish I had studied''. WISH + would (reclamação/irritação): ''I wish he would stop''.', dica = '''If only'' = wish, mas mais dramático.', exemplos = $j$[{"en":"I wish I knew the answer.","pt":"Queria saber a resposta."},{"en":"I wish I had gone to the party.","pt":"Queria ter ido a festa."},{"en":"I wish it would stop raining.","pt":"Queria que parasse de chover."}]$j$::jsonb, questoes = $j$[{"q":"Arrependimento do presente: I wish I ___.","ans":0,"ctx":"","exp":"wish + passado.","opts":["knew","know","have known","will know"]},{"q":"Arrependimento do passado: I wish I ___ harder.","ans":0,"ctx":"","exp":"wish + past perfect.","opts":["had studied","studied","study","would study"]},{"q":"Reclamação: I wish he ___ calling.","ans":0,"ctx":"","exp":"wish + would (irritação).","opts":["would stop","stops","stopped","had stopped"]},{"q":"'If only' é:","ans":0,"ctx":"","exp":"Lamento enfático.","opts":["como wish, mais forte","uma pergunta","um comando","um futuro"]},{"q":"Complete: I wish I ___ taller.","ans":0,"ctx":"","exp":"wish + were (presente irreal).","opts":["were","am","will be","have been"]},{"q":"'I wish I had known' fala de:","ans":0,"ctx":"","exp":"Passado.","opts":["algo no passado","algo no futuro","um hábito","uma ordem"]}]$j$::jsonb where id = 'd0bdd22d-8d25-4c5d-8c3c-cb769bbd81e4';
update licoes set titulo = 'Reported speech avançado II', sub = 'He said he had left', explicacao = 'Ao relatar fala, os tempos recuam (backshift): present->past, past->past perfect, will->would, can->could. Também mudam pronomes e marcadores de tempo (now->then, today->that day).', dica = '''I am tired'' -> He said he was tired. ''I will go'' -> She said she would go.', exemplos = $j$[{"en":"He said he was busy.","pt":"Ele disse que estava ocupado."},{"en":"She said she had finished.","pt":"Ela disse que tinha terminado."},{"en":"They said they would call.","pt":"Eles disseram que ligariam."}]$j$::jsonb, questoes = $j$[{"q":"'I am here' -> He said he ___ there.","ans":0,"ctx":"","exp":"present->past.","opts":["was","is","has been","will be"]},{"q":"'I finished' -> She said she ___.","ans":0,"ctx":"","exp":"past->past perfect.","opts":["had finished","finished","has finished","finishes"]},{"q":"'I will help' -> He said he ___ help.","ans":0,"ctx":"","exp":"will->would.","opts":["would","will","would have","will have"]},{"q":"'now' vira ___ no discurso indireto.","ans":0,"ctx":"","exp":"now->then.","opts":["then","now","today","here"]},{"q":"'I can swim' -> She said she ___ swim.","ans":0,"ctx":"","exp":"can->could.","opts":["could","can","could have","will"]},{"q":"'today' vira:","ans":0,"ctx":"","exp":"today->that day.","opts":["that day","today","this day","now"]}]$j$::jsonb where id = '2e05974a-26d2-47e7-9c3e-25fa4a0fee4c';
update licoes set titulo = 'Passiva com reporting verbs', sub = 'It is said that...', explicacao = 'Estrutura formal para relatar rumores/opiniões: ''It is said that he is rich'' ou ''He is said to be rich''. Comum em notícias. Verbos: say, believe, think, know, report, expect.', dica = 'Duas formas: It is said that + oração / Sujeito + is said + to + infinitivo.', exemplos = $j$[{"en":"It is believed that he left.","pt":"Acredita-se que ele partiu."},{"en":"She is said to be very rich.","pt":"Dizem que ela é muito rica."},{"en":"The company is expected to grow.","pt":"Espera-se que a empresa cresça."}]$j$::jsonb, questoes = $j$[{"q":"Complete: It is ___ that he is guilty.","ans":0,"ctx":"","exp":"It is believed that...","opts":["believed","believe","believing","believes"]},{"q":"Complete: He is said ___ rich.","ans":0,"ctx":"","exp":"is said to be.","opts":["to be","being","is","be"]},{"q":"Essa estrutura é típica de:","ans":0,"ctx":"","exp":"Registro formal.","opts":["notícias/formal","conversa casual","mensagens","gírias"]},{"q":"Complete: The plan is ___ to work.","ans":0,"ctx":"","exp":"is expected to.","opts":["expected","expect","expecting","expects"]},{"q":"'It is known that' significa:","ans":0,"ctx":"","exp":"Sabe-se que (impessoal).","opts":["sabe-se que","eu sei que","conheço","conhecido"]},{"q":"Complete: They are ___ to have won.","ans":0,"ctx":"","exp":"are thought to have.","opts":["thought","think","thinking","thinks"]}]$j$::jsonb where id = 'c21867aa-947e-42da-b0f9-a8da48931768';
update licoes set titulo = 'Reduced relative clauses', sub = 'the man standing there', explicacao = 'Podemos encurtar orações relativas. Ativa: ''the man WHO IS standing'' -> ''the man standing''. Passiva: ''the book WHICH WAS written'' -> ''the book written''. Corta o pronome relativo + verbo be.', dica = 'Ativa vira -ing; passiva vira particípio (-ed/3a coluna).', exemplos = $j$[{"en":"The woman talking is my boss.","pt":"A mulher que esta falando e minha chefe."},{"en":"The letter sent yesterday arrived.","pt":"A carta enviada ontem chegou."},{"en":"People living here are friendly.","pt":"As pessoas que moram aqui são simpáticas."}]$j$::jsonb, questoes = $j$[{"q":"'The man who is waiting' encurta para:","ans":0,"ctx":"","exp":"Ativa -> -ing.","opts":["The man waiting","The man wait","The man to wait","The man waited"]},{"q":"'The car which was stolen' encurta para:","ans":0,"ctx":"","exp":"Passiva -> particípio.","opts":["The car stolen","The car stealing","The car steal","The car to steal"]},{"q":"A forma reduzida ativa usa:","ans":0,"ctx":"","exp":"Gerúndio.","opts":["-ing","-ed sempre","to + verbo","will"]},{"q":"'The book written by her' vem de:","ans":0,"ctx":"","exp":"Passiva reduzida.","opts":["which was written","which writes","who write","that writing"]},{"q":"Reduzir clausulas deixa o texto:","ans":0,"ctx":"","exp":"Mais conciso.","opts":["mais conciso","mais longo","informal","errado"]},{"q":"Complete: The people ___ (que esperam) are tired.","ans":0,"ctx":"","exp":"Ativa -> waiting.","opts":["waiting","waited","to wait","waits"]}]$j$::jsonb where id = '8c8a282d-50dd-49c9-a90b-e861144e1a17';
update licoes set titulo = 'Participle clauses', sub = 'Having finished, she left', explicacao = 'Clausulas participiais economizam palavras. -ing (ativa/simultânea): ''Feeling tired, I slept''. Having + particípio (ação anterior): ''Having eaten, we left''. Particípio passado (passiva): ''Shocked, she froze''.', dica = 'São formais e comuns na escrita. O sujeito das duas partes deve ser o mesmo.', exemplos = $j$[{"en":"Feeling sick, he stayed home.","pt":"Sentindo-se mal, ele ficou em casa."},{"en":"Having read the book, she wrote a review.","pt":"Tendo lido o livro, ela escreveu uma resenha."},{"en":"Built in 1900, the house is old.","pt":"Construída em 1900, a casa é antiga."}]$j$::jsonb, questoes = $j$[{"q":"Ação anterior usa:","ans":0,"ctx":"","exp":"Having eaten...","opts":["Having + particípio","-ing simples","to + verbo","will"]},{"q":"Complete: ___ tired, she rested.","ans":0,"ctx":"","exp":"-ing simultâneo.","opts":["Feeling","Felt","To feel","Feels"]},{"q":"'Built in 1990' é:","ans":0,"ctx":"","exp":"Passiva reduzida.","opts":["particípio passivo","gerúndio","infinitivo","presente"]},{"q":"As duas partes devem ter:","ans":0,"ctx":"","exp":"Mesmo sujeito.","opts":["o mesmo sujeito","sujeitos diferentes","sem sujeito","dois verbos be"]},{"q":"Complete: ___ finished, they went home.","ans":0,"ctx":"","exp":"Having finished.","opts":["Having","Have","Has","To have"]},{"q":"Clausulas participiais são:","ans":0,"ctx":"","exp":"Registro formal.","opts":["formais/escritas","só faladas","erradas","infantis"]}]$j$::jsonb where id = '02eefeb9-12ab-41b3-81d8-b8013ab89ca9';
update licoes set titulo = 'Gerúndio x infinitivo (sentido)', sub = 'stop smoking / stop to smoke', explicacao = 'Alguns verbos mudam de sentido: ''stop smoking'' (parar de fumar) vs ''stop to smoke'' (parar para fumar). ''remember doing'' (lembrar de algo feito) vs ''remember to do'' (lembrar de fazer). ''try doing'' (experimentar) vs ''try to do'' (esforçar-se).', dica = 'Infinitivo = propósito/futuro; gerúndio = ação em si/passado.', exemplos = $j$[{"en":"I stopped to rest.","pt":"Parei para descansar."},{"en":"Remember to lock the door.","pt":"Lembre de trancar a porta."},{"en":"I remember meeting her.","pt":"Lembro de te-la conhecido."}]$j$::jsonb, questoes = $j$[{"q":"'Parar de fumar':","ans":0,"ctx":"","exp":"stop + -ing = cessar.","opts":["stop smoking","stop to smoke","stop smoke","stop for smoke"]},{"q":"'Parou para descansar':","ans":0,"ctx":"","exp":"stop to = propósito.","opts":["stopped to rest","stopped resting","stop rest","stopped rest"]},{"q":"'Lembre de ligar' (tarefa futura):","ans":0,"ctx":"","exp":"remember to = futuro.","opts":["remember to call","remember calling","remember call","remember for call"]},{"q":"'Lembro de ter visto':","ans":0,"ctx":"","exp":"remember + -ing = passado.","opts":["remember seeing","remember to see","remember see","remember for see"]},{"q":"'Experimente ligar de novo' (sugestão):","ans":0,"ctx":"","exp":"try + -ing = experimentar.","opts":["try calling again","try to call","try call","try for call"]},{"q":"Infinitivo (to) costuma indicar:","ans":0,"ctx":"","exp":"Propósito/futuro.","opts":["propósito/futuro","ação passada","hábito","duração"]}]$j$::jsonb where id = '25d70f37-518d-42f3-9b4d-7a2a0f62d9e4';
update licoes set titulo = 'Future perfect / continuous', sub = 'I will have finished by 5', explicacao = 'Future perfect: ação concluída ANTES de um ponto futuro: ''By 6 pm I will have finished''. Future continuous: ação em andamento em um momento futuro: ''This time tomorrow I will be flying''.', dica = '''By + tempo'' pede future perfect. ''At this time'' pede future continuous.', exemplos = $j$[{"en":"By 2030 I will have graduated.","pt":"Até 2030 eu terei me formado."},{"en":"This time tomorrow we will be traveling.","pt":"Amanhã a esta hora estaremos viajando."},{"en":"She will have left by then.","pt":"Ela já terá saído até lá."}]$j$::jsonb, questoes = $j$[{"q":"Complete: By 8, I ___ dinner.","ans":0,"ctx":"","exp":"By + future perfect.","opts":["will have made","will make","will be making","make"]},{"q":"Complete: This time tomorrow I ___.","ans":0,"ctx":"","exp":"Ação em andamento futura.","opts":["will be sleeping","will have slept","sleep","will sleep"]},{"q":"'By then' combina com:","ans":0,"ctx":"","exp":"By then + will have.","opts":["future perfect","present simple","past simple","imperativo"]},{"q":"Future perfect indica ação:","ans":0,"ctx":"","exp":"Concluída antes.","opts":["concluída antes de um ponto futuro","em andamento","habitual","passada"]},{"q":"Complete: In an hour she ___ working.","ans":0,"ctx":"","exp":"Continuous futuro.","opts":["will still be","will have","is","was"]},{"q":"'will have + particípio' é:","ans":0,"ctx":"","exp":"Future perfect.","opts":["future perfect","future continuous","present perfect","past perfect"]}]$j$::jsonb where id = '2a0d246f-d91b-45ea-808d-3ea79176650a';
update licoes set titulo = 'Modais de dedução no passado', sub = 'must have / can''t have', explicacao = 'Para deduzir sobre o passado: ''must have + particípio'' (certeza positiva: deve ter), ''can''t have'' (certeza negativa: não pode ter), ''might/could have'' (possibilidade: talvez tenha).', dica = 'must have = tenho certeza que sim; can''t have = tenho certeza que não.', exemplos = $j$[{"en":"He must have forgotten.","pt":"Ele deve ter esquecido."},{"en":"She can't have seen us.","pt":"Ela não pode ter nos visto."},{"en":"They might have missed the train.","pt":"Eles talvez tenham perdido o trem."}]$j$::jsonb, questoes = $j$[{"q":"Certeza positiva sobre o passado:","ans":0,"ctx":"","exp":"must have = certeza.","opts":["must have left","can't have left","might leave","should leave"]},{"q":"Certeza negativa:","ans":0,"ctx":"","exp":"can't have = impossível.","opts":["can't have known","must have known","might know","could know"]},{"q":"Possibilidade:","ans":0,"ctx":"","exp":"might have = talvez.","opts":["might have gone","must have gone","can't have gone","will go"]},{"q":"Complete: The ground is wet. It ___ rained.","ans":0,"ctx":"","exp":"Dedução lógica: must have.","opts":["must have","can't have","shouldn't have","will have"]},{"q":"'She can't have said that' expressa:","ans":0,"ctx":"","exp":"Impossibilidade percebida.","opts":["forte descrença","certeza positiva","obrigação","permissão"]},{"q":"Todos usam a estrutura:","ans":0,"ctx":"","exp":"modal + have + particípio.","opts":["modal + have + particípio","modal + -ing","modal + to","modal + will"]}]$j$::jsonb where id = '969bce17-981c-4e69-84dc-cafab7167cb0';
update licoes set titulo = 'Despite x Although', sub = 'despite the rain / although it rained', explicacao = 'Mesma ideia (contraste), estruturas diferentes. ALTHOUGH/THOUGH + oração (sujeito+verbo): ''Although it rained, we went''. DESPITE/IN SPITE OF + substantivo ou -ing: ''Despite the rain'' / ''Despite raining''.', dica = 'Nunca ''despite of''. E ''in spite OF'' ou ''despite'' (sem of).', exemplos = $j$[{"en":"Although he was tired, he worked.","pt":"Embora estivesse cansado, ele trabalhou."},{"en":"Despite the cost, they bought it.","pt":"Apesar do custo, compraram."},{"en":"In spite of being ill, she came.","pt":"Apesar de estar doente, ela veio."}]$j$::jsonb, questoes = $j$[{"q":"Complete: ___ the traffic, we arrived.","ans":0,"ctx":"","exp":"Despite + substantivo.","opts":["Despite","Although","Even","But"]},{"q":"Complete: ___ it was late, we stayed.","ans":0,"ctx":"","exp":"Although + oração.","opts":["Although","Despite","In spite","Despite of"]},{"q":"Qual está errado?","ans":0,"ctx":"","exp":"'Despite of' não existe.","opts":["Despite of the rain","Despite the rain","In spite of the rain","Although it rained"]},{"q":"Complete: Despite ___ hard, he failed.","ans":0,"ctx":"","exp":"Despite + -ing.","opts":["working","he worked","work","to work"]},{"q":"'Although' é seguido de:","ans":0,"ctx":"","exp":"Oração completa.","opts":["sujeito + verbo","só substantivo","só -ing","of"]},{"q":"'In spite ___ the noise' completa com:","ans":0,"ctx":"","exp":"in spite of.","opts":["of","on","to","for"]}]$j$::jsonb where id = '7f03a0c3-cd17-42c7-8aa9-ef4c2117cf03';
update licoes set titulo = 'Conectivos formais', sub = 'however / therefore / nevertheless', explicacao = 'Conectores ligam ideias em texto formal. Contraste: however, nevertheless, on the other hand. Resultado: therefore, thus, consequently. Adição: moreover, furthermore. Geralmente vem com vírgula.', dica = 'However = porém; therefore = portanto; moreover = além disso.', exemplos = $j$[{"en":"It was expensive; however, we bought it.","pt":"Era caro; porém, compramos."},{"en":"He was late; therefore, he missed it.","pt":"Ele atrasou; portanto, perdeu."},{"en":"Moreover, the plan saves money.","pt":"Além disso, o plano economiza."}]$j$::jsonb, questoes = $j$[{"q":"'Porém' formal:","ans":0,"ctx":"","exp":"however = contraste.","opts":["however","moreover","therefore","because"]},{"q":"'Portanto':","ans":0,"ctx":"","exp":"therefore = resultado.","opts":["therefore","however","although","moreover"]},{"q":"'Além disso':","ans":0,"ctx":"","exp":"furthermore = adição.","opts":["furthermore","however","therefore","instead"]},{"q":"'Nevertheless' significa:","ans":0,"ctx":"","exp":"Contraste (ainda assim).","opts":["mesmo assim","por isso","por exemplo","primeiro"]},{"q":"'Consequently' indica:","ans":0,"ctx":"","exp":"Consequência.","opts":["resultado","contraste","adição","exemplo"]},{"q":"Esses conectores são mais comuns em:","ans":0,"ctx":"","exp":"Registro formal.","opts":["texto formal","gírias","mensagens","músicas"]}]$j$::jsonb where id = '58978697-788f-4c62-a184-1d064ac8c26b';
update licoes set titulo = 'Phrasal verbs com UP', sub = 'give up / bring up / make up', explicacao = '''Up'' costuma dar ideia de completar ou intensificar. give up (desistir), bring up (criar/mencionar), make up (inventar/reconciliar), come up with (bolar), put up with (tolerar).', dica = 'Muitos são idiomáticos: ''make up'' pode ser inventar OU reconciliar, depende do contexto.', exemplos = $j$[{"en":"Don't give up now.","pt":"Não desista agora."},{"en":"She brought up an interesting point.","pt":"Ela levantou um ponto interessante."},{"en":"I can't put up with this noise.","pt":"Não aguento esse barulho."}]$j$::jsonb, questoes = $j$[{"q":"'Desistir' =","ans":0,"ctx":"","exp":"give up = desistir.","opts":["give up","give in","give out","give away"]},{"q":"'Tolerar/aguentar' =","ans":0,"ctx":"","exp":"put up with.","opts":["put up with","put up","put down","put off"]},{"q":"'Bolar uma ideia' =","ans":0,"ctx":"","exp":"come up with.","opts":["come up with","come up","come across","come over"]},{"q":"'Bring up' pode significar:","ans":0,"ctx":"","exp":"Criar/mencionar.","opts":["criar (filhos) ou mencionar","derrubar","esconder","vender"]},{"q":"'Make up a story' =","ans":0,"ctx":"","exp":"make up = inventar.","opts":["inventar","escrever bem","traduzir","corrigir"]},{"q":"'Up' nesses verbos costuma dar ideia de:","ans":0,"ctx":"","exp":"Completude/intensidade.","opts":["completar/intensificar","descer","parar","repetir"]}]$j$::jsonb where id = '4a47c783-87c8-4e64-9d21-2fdc8ab0ac21';
update licoes set titulo = 'Colocações com TAKE', sub = 'take part / take advantage', explicacao = 'TAKE forma muitas colocações fixas: take part (participar), take advantage of (aproveitar-se), take place (acontecer), take care of (cuidar), take into account (levar em conta), take responsibility.', dica = 'Memorize como blocos: ''take place'' = ocorrer, não ''happen place''.', exemplos = $j$[{"en":"The meeting takes place at noon.","pt":"A reunião acontece ao meio-dia."},{"en":"We took advantage of the offer.","pt":"Aproveitamos a oferta."},{"en":"Please take this into account.","pt":"Por favor leve isso em conta."}]$j$::jsonb, questoes = $j$[{"q":"'Acontecer' =","ans":0,"ctx":"","exp":"take place.","opts":["take place","take part","take care","take time"]},{"q":"'Participar' =","ans":0,"ctx":"","exp":"take part in.","opts":["take part in","take place","take part of","make part"]},{"q":"'Levar em conta' =","ans":0,"ctx":"","exp":"take into account.","opts":["take into account","take account","take in count","make account"]},{"q":"'Cuidar de' =","ans":0,"ctx":"","exp":"take care of.","opts":["take care of","take care","make care of","give care"]},{"q":"'Aproveitar-se de' =","ans":0,"ctx":"","exp":"take advantage of.","opts":["take advantage of","take advantage","make advantage","get advantage"]},{"q":"Colocações são:","ans":0,"ctx":"","exp":"Combinações naturais fixas.","opts":["combinações fixas de palavras","gírias","erros","abreviações"]}]$j$::jsonb where id = '13fa8c19-256b-4a42-a9d6-ae792e074867';
update licoes set titulo = 'Adjetivo + preposição III', sub = 'good at / afraid of', explicacao = 'Adjetivos pedem preposições fixas: good AT, afraid OF, interested IN, proud OF, keen ON, responsible FOR, similar TO, different FROM. São arbitrárias - memorize.', dica = 'Cuidado: ''good in'' esta errado; e ''good AT''.', exemplos = $j$[{"en":"She is good at math.","pt":"Ela é boa em matemática."},{"en":"I'm interested in art.","pt":"Tenho interesse em arte."},{"en":"He's afraid of dogs.","pt":"Ele tem medo de cachorros."}]$j$::jsonb, questoes = $j$[{"q":"good ___ something","ans":0,"ctx":"","exp":"good at.","opts":["at","in","on","of"]},{"q":"afraid ___ spiders","ans":0,"ctx":"","exp":"afraid of.","opts":["of","to","for","with"]},{"q":"interested ___ music","ans":0,"ctx":"","exp":"interested in.","opts":["in","on","at","for"]},{"q":"proud ___ you","ans":0,"ctx":"","exp":"proud of.","opts":["of","for","with","at"]},{"q":"responsible ___ the team","ans":0,"ctx":"","exp":"responsible for.","opts":["for","of","to","on"]},{"q":"different ___ mine (US)","ans":0,"ctx":"","exp":"different from.","opts":["from","than","of","to"]}]$j$::jsonb where id = 'c4b9da65-d9d0-429e-8a8f-462b26d1a21b';
update licoes set titulo = 'Verbo + preposição', sub = 'depend on / apologize for', explicacao = 'Verbos pedem preposições fixas: depend ON, apologize FOR, believe IN, succeed IN, insist ON, rely ON, deal WITH, consist OF, accuse OF. Memorize por uso.', dica = '''Depend of'' esta errado; e ''depend ON''.', exemplos = $j$[{"en":"It depends on you.","pt":"Depende de você."},{"en":"She apologized for the delay.","pt":"Ela se desculpou pelo atraso."},{"en":"We rely on teamwork.","pt":"Contamos com o trabalho em equipe."}]$j$::jsonb, questoes = $j$[{"q":"depend ___ someone","ans":0,"ctx":"","exp":"depend on.","opts":["on","of","in","to"]},{"q":"apologize ___ a mistake","ans":0,"ctx":"","exp":"apologize for.","opts":["for","of","about","to"]},{"q":"believe ___ yourself","ans":0,"ctx":"","exp":"believe in.","opts":["in","on","of","at"]},{"q":"consist ___ three parts","ans":0,"ctx":"","exp":"consist of.","opts":["of","in","on","with"]},{"q":"deal ___ a problem","ans":0,"ctx":"","exp":"deal with.","opts":["with","on","of","for"]},{"q":"insist ___ paying","ans":0,"ctx":"","exp":"insist on.","opts":["on","in","at","for"]}]$j$::jsonb where id = 'ea041031-4bb2-4ab2-96da-4ee705bd02a2';
update licoes set titulo = 'Ênfase com so / such', sub = 'so tired / such a day', explicacao = 'Para intensificar: SO + adjetivo/adverbio (so tired, so quickly). SUCH + (a/an) + adjetivo + substantivo (such a nice day, such good food). Uncountable/plural não leva a/an: such nice weather.', dica = 'so = com adjetivo sozinho; such = quando ha substantivo.', exemplos = $j$[{"en":"It was so cold.","pt":"Estava tao frio."},{"en":"It was such a cold day.","pt":"Foi um dia tao frio."},{"en":"They have such nice ideas.","pt":"Eles tem ideias tao boas."}]$j$::jsonb, questoes = $j$[{"q":"Complete: She is ___ kind.","ans":0,"ctx":"","exp":"so + adjetivo.","opts":["so","such","such a","very such"]},{"q":"Complete: It was ___ good film.","ans":0,"ctx":"","exp":"such a + adj + subst.","opts":["such a","so","so a","such"]},{"q":"Complete: The food was ___ delicious.","ans":0,"ctx":"","exp":"so + adjetivo.","opts":["so","such","such a","so a"]},{"q":"Complete: ___ nice people!","ans":0,"ctx":"","exp":"such (plural, sem a).","opts":["Such","So","Such a","So a"]},{"q":"Complete: We had ___ fun.","ans":0,"ctx":"","exp":"such + uncountable.","opts":["such","such a","so a","a so"]},{"q":"'So' é usado com:","ans":0,"ctx":"","exp":"so + adj/adv.","opts":["adjetivo/advérbio","substantivo + a","verbo","artigo"]}]$j$::jsonb where id = '1a832284-98f1-4660-b847-079bcde365d8';
update licoes set titulo = 'Substantivos incontáveis', sub = 'advice / information / news', explicacao = 'Muitos substantivos são incontáveis em inglês (mas contáveis em português): advice, information, news, furniture, luggage, equipment, research, knowledge. Não usam ''a/an'' nem plural. Use ''a piece of'' para contar.', dica = 'Errado: ''an advice'', ''informations''. Certo: ''a piece of advice'', ''information''.', exemplos = $j$[{"en":"Let me give you some advice.","pt":"Deixe-me te dar um conselho."},{"en":"I need more information.","pt":"Preciso de mais informações."},{"en":"The news is good.","pt":"As notícias são boas."}]$j$::jsonb, questoes = $j$[{"q":"Qual está correto?","ans":0,"ctx":"","exp":"advice é incontável.","opts":["some advice","an advice","advices","many advice"]},{"q":"'Uma informação' =","ans":0,"ctx":"","exp":"a piece of information.","opts":["a piece of information","an information","one information","a information"]},{"q":"'News' leva verbo:","ans":0,"ctx":"","exp":"The news IS...","opts":["singular (is)","plural (are)","os dois","nenhum"]},{"q":"Qual é incontável?","ans":0,"ctx":"","exp":"furniture é incontável.","opts":["furniture","chair","table","book"]},{"q":"Qual está errado?","ans":0,"ctx":"","exp":"luggage não pluraliza.","opts":["two luggages","some luggage","a lot of luggage","my luggage"]},{"q":"'Research' no plural:","ans":0,"ctx":"","exp":"Incontável.","opts":["não pluraliza (research)","researches","researchs","researchies"]}]$j$::jsonb where id = 'c90c63dc-d4f7-4b10-89d6-7643952c2d2d';
update licoes set titulo = 'Artigos avançados', sub = 'the / a / zero article', explicacao = 'Uso genérico: sem artigo para plural/incontável geral (I like music; Dogs are loyal). THE para algo específico ou único (the sun, the government). Sem artigo com refeições, esportes, idiomas (have lunch, play tennis, speak French).', dica = 'Generalização no plural = sem artigo. Específico = the.', exemplos = $j$[{"en":"Music makes me happy.","pt":"Música me deixa feliz."},{"en":"The music at the party was loud.","pt":"A música na festa estava alta."},{"en":"She plays tennis on Sundays.","pt":"Ela joga tênis aos domingos."}]$j$::jsonb, questoes = $j$[{"q":"Geral: I love ___ (cachorros).","ans":0,"ctx":"","exp":"Genérico = sem the.","opts":["dogs","the dogs","a dogs","dog"]},{"q":"Complete: ___ sun is bright.","ans":0,"ctx":"","exp":"the sun (único).","opts":["The","A","An","(nada)"]},{"q":"Complete: Let's have ___ lunch.","ans":0,"ctx":"","exp":"Refeições sem artigo.","opts":["(nada)","the","a","an"]},{"q":"Complete: He speaks ___ English.","ans":0,"ctx":"","exp":"Idiomas sem artigo.","opts":["(nada)","the","a","an"]},{"q":"Complete: I read ___ book you gave me.","ans":0,"ctx":"","exp":"Específico = the.","opts":["the","a","an","(nada)"]},{"q":"Generalização no plural usa:","ans":0,"ctx":"","exp":"Sem artigo.","opts":["zero artigo","the sempre","a/an","this"]}]$j$::jsonb where id = '7f2355af-4c92-4725-becf-1943e08ab523';
update licoes set titulo = 'Suavizar opiniões (hedging)', sub = 'It seems / I would say', explicacao = 'Em inglês formal/educado, suavizamos afirmações: ''It seems that...'', ''It tends to...'', ''I would say...'', ''It might be...'', ''to some extent'', ''apparently''. Soa menos categórico e mais profissional.', dica = 'Evite afirmar 100%: prefira ''it appears'' a ''it is''.', exemplos = $j$[{"en":"It seems to be a good idea.","pt":"Parece ser uma boa ideia."},{"en":"I would say it's too expensive.","pt":"Eu diria que é caro demais."},{"en":"This tends to happen often.","pt":"Isso costuma acontecer com frequência."}]$j$::jsonb, questoes = $j$[{"q":"Suaviza 'This is wrong':","ans":0,"ctx":"","exp":"Hedging educado.","opts":["This may not be quite right","This is totally wrong","Wrong!","No way"]},{"q":"'I would say' serve para:","ans":0,"ctx":"","exp":"Opinião suave.","opts":["dar opinião com cautela","ordenar","negar tudo","perguntar"]},{"q":"'It tends to' indica:","ans":0,"ctx":"","exp":"Tendência.","opts":["tendência (não regra fixa)","certeza absoluta","proibição","passado"]},{"q":"'To some extent' =","ans":0,"ctx":"","exp":"Parcialmente.","opts":["em certa medida","totalmente","nunca","de novo"]},{"q":"Hedging deixa o discurso:","ans":0,"ctx":"","exp":"Educado.","opts":["mais educado/profissional","grosseiro","infantil","confuso"]},{"q":"Mais cauteloso:","ans":0,"ctx":"","exp":"'appears' suaviza.","opts":["It appears to be true","It is definitely true","Obviously true","100% true"]}]$j$::jsonb where id = '756a05ae-2b76-462c-9389-40f4bb650bd2';
update licoes set titulo = 'E-mails formais', sub = 'I am writing to / Please find', explicacao = 'Frases fixas de e-mail profissional: abertura ''I am writing to...'', ''I hope this email finds you well''. Pedido ''I would appreciate it if...'', ''Could you please...''. Anexo ''Please find attached''. Fecho ''Best regards'', ''Kind regards''.', dica = 'Evite gírias. Prefira ''I would appreciate'' a ''I want''.', exemplos = $j$[{"en":"I am writing to inquire about the role.","pt":"Escrevo para perguntar sobre a vaga."},{"en":"Please find attached my resume.","pt":"Segue anexo meu currículo."},{"en":"I look forward to your reply.","pt":"Aguardo seu retorno."}]$j$::jsonb, questoes = $j$[{"q":"Abertura formal:","ans":0,"ctx":"","exp":"Registro formal.","opts":["I am writing to...","Hey what's up","Yo","Sup"]},{"q":"'Segue anexo' =","ans":0,"ctx":"","exp":"Please find attached.","opts":["Please find attached","Here is the thing","Look attach","Attach please find"]},{"q":"Fecho profissional:","ans":0,"ctx":"","exp":"Best regards.","opts":["Best regards","Bye bye","See ya","Later"]},{"q":"Pedido educado:","ans":0,"ctx":"","exp":"Pedido formal.","opts":["I would appreciate it if you could","Do it now","You must","I want"]},{"q":"'Aguardo seu retorno':","ans":0,"ctx":"","exp":"look forward to.","opts":["I look forward to your reply","Answer me fast","Reply now","Waiting you"]},{"q":"Em e-mail formal, evite:","ans":0,"ctx":"","exp":"Nada de gírias.","opts":["gírias e emojis","saudação","assinatura","assunto claro"]}]$j$::jsonb where id = 'a572d0af-a5d0-4b25-9cb7-591ff751af66';
update licoes set titulo = 'Idioms de trabalho', sub = 'ballpark figure / think outside the box', explicacao = 'Expressões comuns no trabalho: think outside the box (pensar diferente), ballpark figure (estimativa aproximada), touch base (dar um retorno), on the same page (em sintonia), get the ball rolling (começar).', dica = 'São idiomáticas: ''touch base'' não tem a ver com beisebol literal.', exemplos = $j$[{"en":"Let's touch base next week.","pt":"Vamos nos falar semana que vem."},{"en":"We need to think outside the box.","pt":"Precisamos pensar fora da caixa."},{"en":"Are we on the same page?","pt":"Estamos em sintonia?"}]$j$::jsonb, questoes = $j$[{"q":"'Think outside the box' =","ans":0,"ctx":"","exp":"Criatividade.","opts":["pensar de forma criativa","guardar em caixa","trabalhar sozinho","copiar"]},{"q":"'Ballpark figure' =","ans":0,"ctx":"","exp":"Estimativa.","opts":["estimativa aproximada","valor exato","campo de beisebol","erro"]},{"q":"'Touch base' =","ans":0,"ctx":"","exp":"Alinhar rapidamente.","opts":["dar um retorno/alinhar","tocar algo","viajar","cancelar"]},{"q":"'On the same page' =","ans":0,"ctx":"","exp":"De acordo.","opts":["em sintonia/de acordo","na mesma pagina do livro","atrasado","confuso"]},{"q":"'Get the ball rolling' =","ans":0,"ctx":"","exp":"Iniciar.","opts":["começar algo","terminar","jogar bola","esperar"]},{"q":"Esses idioms são:","ans":0,"ctx":"","exp":"Business idioms.","opts":["comuns no ambiente de trabalho","só em esportes","erros","formais demais"]}]$j$::jsonb where id = '03fec3cf-326a-432c-9f60-6029edbcae17';
update licoes set titulo = 'Idioms de tempo e dinheiro', sub = 'in the nick of time / cost a fortune', explicacao = 'Tempo: in the nick of time (no último segundo), against the clock (contra o relógio), call it a day (encerrar). Dinheiro: cost a fortune (custar caro), tighten your belt (economizar), break the bank (gastar muito).', dica = 'Idioms não são literais: ''break the bank'' não é assaltar banco.', exemplos = $j$[{"en":"We finished in the nick of time.","pt":"Terminamos no último segundo."},{"en":"That car cost a fortune.","pt":"Aquele carro custou uma fortuna."},{"en":"Let's call it a day.","pt":"Vamos encerrar por hoje."}]$j$::jsonb, questoes = $j$[{"q":"'In the nick of time' =","ans":0,"ctx":"","exp":"Bem em cima da hora.","opts":["no último instante","com atraso","cedo demais","nunca"]},{"q":"'Cost a fortune' =","ans":0,"ctx":"","exp":"Muito caro.","opts":["custar muito caro","ser barato","ser gratis","dar sorte"]},{"q":"'Call it a day' =","ans":0,"ctx":"","exp":"Parar/encerrar.","opts":["encerrar por hoje","marcar um dia","ligar de dia","começar"]},{"q":"'Tighten your belt' =","ans":0,"ctx":"","exp":"Cortar gastos.","opts":["economizar","engordar","apertar o cinto do carro","gastar"]},{"q":"'Against the clock' =","ans":0,"ctx":"","exp":"Correndo contra o tempo.","opts":["com pouco tempo","sem pressa","no relógio","atrasado"]},{"q":"'Break the bank' =","ans":0,"ctx":"","exp":"Gasto alto.","opts":["gastar muito","roubar banco","quebrar algo","poupar"]}]$j$::jsonb where id = 'fb7faae1-981b-46e1-989e-c8e46dd66e8e';
update licoes set titulo = 'Pares confusos I', sub = 'affect x effect', explicacao = 'Erros clássicos: AFFECT (verbo: afetar) x EFFECT (substantivo: efeito). ADVICE (subst: conselho) x ADVISE (verbo: aconselhar). PRACTICE (subst) x PRACTISE (verbo, UK). LOSE (perder) x LOOSE (frouxo).', dica = 'Dica: ''The effect'' (com the = substantivo). ''It affects me'' (verbo).', exemplos = $j$[{"en":"The weather affects my mood.","pt":"O tempo afeta meu humor."},{"en":"It had a big effect.","pt":"Teve um grande efeito."},{"en":"Can you advise me?","pt":"Pode me aconselhar?"}]$j$::jsonb, questoes = $j$[{"q":"Verbo 'afetar':","ans":0,"ctx":"","exp":"affect = verbo.","opts":["affect","effect","afect","efect"]},{"q":"Substantivo 'efeito':","ans":0,"ctx":"","exp":"effect = substantivo.","opts":["effect","affect","efect","affekt"]},{"q":"'Me aconselhe' (verbo):","ans":0,"ctx":"","exp":"advise = verbo.","opts":["advise me","advice me","advize me","advis me"]},{"q":"'Um conselho' (substantivo):","ans":0,"ctx":"","exp":"advice = substantivo.","opts":["advice","advise","advize","advis"]},{"q":"'Perder as chaves':","ans":0,"ctx":"","exp":"lose = perder.","opts":["lose the keys","loose the keys","loos the keys","loss the keys"]},{"q":"'Frouxo/solto':","ans":0,"ctx":"","exp":"loose = frouxo.","opts":["loose","lose","loss","loos"]}]$j$::jsonb where id = '4541d68d-25a0-42ca-acf5-0f8e9981246c';
update licoes set titulo = 'Pares confusos II', sub = 'raise x rise / lie x lay', explicacao = 'RAISE (transitivo: levantar algo - raise your hand) x RISE (intransitivo: subir sozinho - prices rise). LIE (deitar-se: lie/lay/lain) x LAY (colocar algo: lay/laid/laid). Confundir é comum até para nativos.', dica = 'raise precisa de objeto; rise não. lay precisa de objeto; lie não.', exemplos = $j$[{"en":"Please raise your hand.","pt":"Por favor levante a mao."},{"en":"The sun rises in the east.","pt":"O sol nasce no leste."},{"en":"I need to lie down.","pt":"Preciso me deitar."}]$j$::jsonb, questoes = $j$[{"q":"Levantar algo (com objeto):","ans":0,"ctx":"","exp":"raise + objeto.","opts":["raise","rise","raus","risen"]},{"q":"Subir sozinho (sem objeto):","ans":0,"ctx":"","exp":"rise (intransitivo).","opts":["rise","raise","raises it","rose it"]},{"q":"'Me deitar':","ans":0,"ctx":"","exp":"lie = deitar-se.","opts":["lie down","lay down myself","laid down","lie it down"]},{"q":"'Colocar o livro na mesa':","ans":0,"ctx":"","exp":"lay + objeto.","opts":["lay the book","lie the book","lied the book","rise the book"]},{"q":"Passado de 'rise':","ans":0,"ctx":"","exp":"rise-rose-risen.","opts":["rose","raised","risen","rised"]},{"q":"'Raise' exige:","ans":0,"ctx":"","exp":"Transitivo.","opts":["um objeto","nenhum objeto","gerúndio","preposição"]}]$j$::jsonb where id = 'aa5ea396-8b1b-406b-ada5-2a113c4f6d75';
update licoes set titulo = 'Idioms com partes do corpo II', sub = 'pull someone''s leg', explicacao = 'Muitos idioms usam o corpo: pull someone''s leg (brincar/zoar), cost an arm and a leg (custar caro), keep an eye on (vigiar), get cold feet (amarelar), by the skin of your teeth (por pouco).', dica = 'Não são literais: ''pull your leg'' é brincadeira, não puxar a perna.', exemplos = $j$[{"en":"Are you pulling my leg?","pt":"Você está me zoando?"},{"en":"It cost an arm and a leg.","pt":"Custou os olhos da cara."},{"en":"He got cold feet before the wedding.","pt":"Ele amarelou antes do casamento."}]$j$::jsonb, questoes = $j$[{"q":"'Pull someone's leg' =","ans":0,"ctx":"","exp":"Fazer graça.","opts":["brincar/zoar","puxar a perna","ajudar","correr"]},{"q":"'Cost an arm and a leg' =","ans":0,"ctx":"","exp":"Muito caro.","opts":["custar muito caro","ser barato","machucar","ser gratis"]},{"q":"'Keep an eye on' =","ans":0,"ctx":"","exp":"Vigiar.","opts":["vigiar/ficar de olho","fechar o olho","piscar","ignorar"]},{"q":"'Get cold feet' =","ans":0,"ctx":"","exp":"Perder a coragem.","opts":["ficar com medo/amarelar","sentir frio","correr","dormir"]},{"q":"'By the skin of your teeth' =","ans":0,"ctx":"","exp":"Escapar por pouco.","opts":["por muito pouco","com forca","com folga","com sorte total"]},{"q":"Idioms de corpo são:","ans":0,"ctx":"","exp":"Sentido figurado.","opts":["figurados, não literais","sempre literais","gramática","gírias erradas"]}]$j$::jsonb where id = '3a6d569d-bb2b-4cc4-90ce-f1e03ad89198';
update licoes set titulo = 'Idioms com clima', sub = 'under the weather', explicacao = 'Clima vira sentimento: under the weather (indisposto), a storm in a teacup (tempestade em copo d''água), take a rain check (fica pra próxima), on cloud nine (nas nuvens/muito feliz), steal someone''s thunder (roubar a cena).', dica = '''Under the weather'' = meio doente, não sobre o tempo.', exemplos = $j$[{"en":"I'm feeling under the weather.","pt":"Estou meio indisposto."},{"en":"Can I take a rain check?","pt":"Podemos deixar para outra hora?"},{"en":"She was on cloud nine.","pt":"Ela estava nas nuvens."}]$j$::jsonb, questoes = $j$[{"q":"'Under the weather' =","ans":0,"ctx":"","exp":"Adoentado.","opts":["indisposto/meio doente","com frio","molhado","feliz"]},{"q":"'Take a rain check' =","ans":0,"ctx":"","exp":"Fica pra próxima.","opts":["adiar para outra vez","checar a chuva","cancelar de vez","aceitar"]},{"q":"'On cloud nine' =","ans":0,"ctx":"","exp":"Nas nuvens.","opts":["extremamente feliz","confuso","no avião","triste"]},{"q":"'A storm in a teacup' =","ans":0,"ctx":"","exp":"Tempestade em copo d'água.","opts":["exagero por algo pequeno","tempestade real","chá quente","problema sério"]},{"q":"'Steal someone's thunder' =","ans":0,"ctx":"","exp":"Roubar a cena.","opts":["roubar a atenção/o mérito","roubar dinheiro","trovão","assustar"]},{"q":"Idioms de clima descrevem:","ans":0,"ctx":"","exp":"Sentido figurado.","opts":["sentimentos/situações","só o tempo","gramática","números"]}]$j$::jsonb where id = '4e2fdbfc-4956-4a7b-a141-898ca8d4f894';
update licoes set titulo = 'Sinônimos de BIG', sub = 'large / huge / vast / immense', explicacao = '''Big'' tem nuances: large (grande, neutro/formal), huge (enorme), vast (vasto - areas/quantidades), enormous/immense (imenso), gigantic (gigantesco). A escolha muda a intensidade e o registro.', dica = '''Vast'' combina com espaço/quantia (a vast desert), não com pessoas.', exemplos = $j$[{"en":"A vast desert stretched ahead.","pt":"Um vasto deserto se estendia."},{"en":"There was a huge crowd.","pt":"Havia uma multidão enorme."},{"en":"The costs were immense.","pt":"Os custos foram imensos."}]$j$::jsonb, questoes = $j$[{"q":"Mais forte que 'big':","ans":0,"ctx":"","exp":"enormous = muito grande.","opts":["enormous","little","small","tiny"]},{"q":"'Vast' combina melhor com:","ans":0,"ctx":"","exp":"Areas/quantidades.","opts":["a vast area","a vast baby","a vast smile","a vast pen"]},{"q":"Mais formal/neutro que 'big':","ans":0,"ctx":"","exp":"large = formal.","opts":["large","huge","gigantic","massive"]},{"q":"'Immense' significa:","ans":0,"ctx":"","exp":"Muito grande.","opts":["imenso","minusculo","médio","vazio"]},{"q":"Escolher o sinônimo certo afeta:","ans":0,"ctx":"","exp":"Nuance.","opts":["intensidade e registro","só a pronúncia","o tempo verbal","a ordem"]},{"q":"Exagero coloquial de 'big':","ans":0,"ctx":"","exp":"massive = informal enfático.","opts":["massive","large","sizeable","considerable"]}]$j$::jsonb where id = '3a4393a4-cceb-440e-b935-7cf83cf40a26';
update licoes set titulo = 'Sinônimos de HAPPY', sub = 'glad / delighted / thrilled', explicacao = 'Graus de felicidade: glad (contente, leve), pleased (satisfeito, formal), delighted (muito feliz, educado), thrilled (empolgadíssimo), content (tranquilo/satisfeito), overjoyed (radiante).', dica = '''Delighted'' e educado e forte: ''I''d be delighted to help''.', exemplos = $j$[{"en":"I'm delighted to meet you.","pt":"Estou encantado em conhecê-lo."},{"en":"She was thrilled with the news.","pt":"Ela ficou empolgadíssima com a notícia."},{"en":"He felt content with life.","pt":"Ele se sentia satisfeito com a vida."}]$j$::jsonb, questoes = $j$[{"q":"Muito feliz e educado:","ans":0,"ctx":"","exp":"delighted.","opts":["delighted","glad","okay","fine"]},{"q":"Empolgadíssimo:","ans":0,"ctx":"","exp":"thrilled.","opts":["thrilled","content","pleased","glad"]},{"q":"Contente de forma leve:","ans":0,"ctx":"","exp":"glad = leve.","opts":["glad","overjoyed","thrilled","ecstatic"]},{"q":"'Content' sugere:","ans":0,"ctx":"","exp":"Satisfeito/em paz.","opts":["satisfação tranquila","euforia","raiva","medo"]},{"q":"Mais formal que 'happy':","ans":0,"ctx":"","exp":"pleased = formal.","opts":["pleased","stoked","chuffed","over the moon"]},{"q":"'Over the moon' é:","ans":0,"ctx":"","exp":"Muito feliz, coloquial.","opts":["felicíssimo (informal)","triste","cansado","neutro"]}]$j$::jsonb where id = 'f6de3c8f-e7dc-4a13-abdc-e8d6339fe51d';
update licoes set titulo = 'Conotação', sub = 'slim x skinny x thin', explicacao = 'Palavras parecidas carregam julgamento. Magro: slim (positivo), thin (neutro), skinny (negativo, magro demais). Curioso: curious (positivo) x nosy (bisbilhoteiro). Econômico: thrifty (positivo) x stingy (pão-duro).', dica = 'A conotação revela sua opinião: ''slim'' elogia, ''skinny'' critica.', exemplos = $j$[{"en":"She looks slim and healthy.","pt":"Ela parece magra e saudável."},{"en":"He's too skinny.","pt":"Ele está magro demais."},{"en":"My neighbor is very nosy.","pt":"Meu vizinho é muito bisbilhoteiro."}]$j$::jsonb, questoes = $j$[{"q":"'Magro' com conotação positiva:","ans":0,"ctx":"","exp":"slim = elogio.","opts":["slim","skinny","bony","scrawny"]},{"q":"'Magro demais' (negativo):","ans":0,"ctx":"","exp":"skinny = crítica.","opts":["skinny","slim","slender","trim"]},{"q":"'Curioso' negativo:","ans":0,"ctx":"","exp":"nosy = bisbilhoteiro.","opts":["nosy","curious","interested","keen"]},{"q":"'Econômico' positivo:","ans":0,"ctx":"","exp":"thrifty = elogio.","opts":["thrifty","stingy","mean","tight"]},{"q":"'Stingy' significa:","ans":0,"ctx":"","exp":"Conotação negativa.","opts":["pão-duro (negativo)","generoso","econômico elogioso","rico"]},{"q":"Conotação é:","ans":0,"ctx":"","exp":"Julgamento embutido.","opts":["a carga emocional da palavra","o som","o plural","o tempo"]}]$j$::jsonb where id = 'f35a3c22-ce39-44b4-bce7-bbe65fe7e81d';
update licoes set titulo = 'Registro: formal x informal', sub = 'purchase x buy', explicacao = 'Muitas ideias tem versão formal e informal. buy/purchase, ask/enquire, help/assist, get/obtain, need/require, start/commence, end/terminate, about/regarding. O formal soa profissional; o informal, natural.', dica = 'Em documentos/negócios use o formal; entre amigos, o informal.', exemplos = $j$[{"en":"You may purchase tickets online.","pt":"Você pode comprar ingressos online."},{"en":"Please do not hesitate to enquire.","pt":"Não hesite em perguntar."},{"en":"The event will commence at noon.","pt":"O evento começará ao meio-dia."}]$j$::jsonb, questoes = $j$[{"q":"Formal de 'buy':","ans":0,"ctx":"","exp":"purchase = formal.","opts":["purchase","grab","get","pick up"]},{"q":"Formal de 'ask (info)':","ans":0,"ctx":"","exp":"enquire.","opts":["enquire","ask","wonder","check"]},{"q":"Formal de 'help':","ans":0,"ctx":"","exp":"assist.","opts":["assist","help out","give a hand","back up"]},{"q":"Formal de 'need':","ans":0,"ctx":"","exp":"require.","opts":["require","need","want","gotta have"]},{"q":"Formal de 'start':","ans":0,"ctx":"","exp":"commence.","opts":["commence","kick off","get going","start up"]},{"q":"Registro formal é ideal para:","ans":0,"ctx":"","exp":"Contexto formal.","opts":["documentos/negócios","bate-papo","memes","música pop"]}]$j$::jsonb where id = 'ec7e430b-945f-4104-b2c5-8f0319fa46f0';
update licoes set titulo = 'Intensificadores fortes', sub = 'utterly / bitterly / highly', explicacao = 'Advérbios de grau colocam fortemente: utterly (completamente - utterly ridiculous), bitterly (amargamente - bitterly disappointed), highly (altamente - highly likely), deeply (profundamente), fully (plenamente). Cada um combina com certos adjetivos.', dica = 'Colocação fixa: ''bitterly cold'', ''highly unlikely'', ''deeply moved''.', exemplos = $j$[{"en":"It's highly unlikely.","pt":"É altamente improvável."},{"en":"She was bitterly disappointed.","pt":"Ela ficou amargamente decepcionada."},{"en":"That's utterly absurd.","pt":"Isso é completamente absurdo."}]$j$::jsonb, questoes = $j$[{"q":"Complete: ___ likely","ans":0,"ctx":"","exp":"highly likely.","opts":["highly","bitterly","utterly","deeply"]},{"q":"Complete: ___ disappointed","ans":0,"ctx":"","exp":"bitterly disappointed.","opts":["bitterly","highly","fully","widely"]},{"q":"Complete: ___ ridiculous","ans":0,"ctx":"","exp":"utterly ridiculous.","opts":["utterly","highly","bitterly","closely"]},{"q":"Complete: ___ cold","ans":0,"ctx":"","exp":"bitterly cold.","opts":["bitterly","highly","deeply","fully"]},{"q":"Complete: ___ moved (emocionado)","ans":0,"ctx":"","exp":"deeply moved.","opts":["deeply","highly","bitterly","widely"]},{"q":"Intensificadores combinam:","ans":0,"ctx":"","exp":"Colocações fixas.","opts":["por colocação fixa","com qualquer palavra","só com verbos","só no passado"]}]$j$::jsonb where id = '00721b0b-bcf4-4c6a-b8a1-15fd020dd75b';
update licoes set titulo = 'Phrasal verbs de negócios', sub = 'roll out / scale up / wind down', explicacao = 'Inglês corporativo: roll out (lançar), scale up/down (aumentar/reduzir escala), wind down (desacelerar/encerrar), branch out (diversificar), carry out (executar), lay off (demitir), pull off (conseguir apesar da dificuldade).', dica = '''Roll out a product'' = lançar gradualmente.', exemplos = $j$[{"en":"We'll roll out the new app in June.","pt":"Vamos lançar o novo app em junho."},{"en":"The company scaled up quickly.","pt":"A empresa cresceu rápido."},{"en":"They laid off 200 workers.","pt":"Demitiram 200 funcionários."}]$j$::jsonb, questoes = $j$[{"q":"'Roll out' =","ans":0,"ctx":"","exp":"Lançamento.","opts":["lançar (gradualmente)","enrolar","cancelar","esconder"]},{"q":"'Scale up' =","ans":0,"ctx":"","exp":"Crescer.","opts":["aumentar a escala","reduzir","medir","escalar montanha"]},{"q":"'Lay off' =","ans":0,"ctx":"","exp":"Demitir.","opts":["demitir","contratar","descansar","atrasar"]},{"q":"'Wind down' =","ans":0,"ctx":"","exp":"Reduzir ritmo.","opts":["desacelerar/encerrar","acelerar","ventar","subir"]},{"q":"'Carry out' =","ans":0,"ctx":"","exp":"Executar.","opts":["executar/realizar","carregar para fora","cancelar","adiar"]},{"q":"'Pull off' (um plano) =","ans":0,"ctx":"","exp":"Ter sucesso.","opts":["conseguir apesar da dificuldade","puxar","desistir","estragar"]}]$j$::jsonb where id = '68e19b4a-9730-4a45-b9c4-657bd826a469';
update licoes set titulo = 'Marcadores de discurso', sub = 'mind you / come to think of it', explicacao = 'Naturalidade vem de marcadores: mind you (olha, no entanto), come to think of it (pensando bem), as it happens (por acaso), that said (dito isso), to be fair (para ser justo), by the way (a propósito).', dica = '''Mind you'' introduz uma ressalva; ''come to think of it'', uma lembrança.', exemplos = $j$[{"en":"He's rude. Mind you, he's honest.","pt":"Ele é grosso. Mas, veja bem, é honesto."},{"en":"Come to think of it, she did call.","pt":"Pensando bem, ela ligou sim."},{"en":"That said, we should try.","pt":"Dito isso, devemos tentar."}]$j$::jsonb, questoes = $j$[{"q":"'Mind you' introduz:","ans":0,"ctx":"","exp":"Ressalva.","opts":["uma ressalva","uma ordem","um pedido","uma pergunta"]},{"q":"'Come to think of it' =","ans":0,"ctx":"","exp":"Lembrança súbita.","opts":["pensando bem","esqueça","definitivamente","de novo"]},{"q":"'That said' =","ans":0,"ctx":"","exp":"Transição com ressalva.","opts":["dito isso (contraste)","ele disse","cale-se","concordo"]},{"q":"'To be fair' =","ans":0,"ctx":"","exp":"Ponderar.","opts":["para ser justo","com raiva","de novo","por fim"]},{"q":"'By the way' =","ans":0,"ctx":"","exp":"Mudar de assunto.","opts":["a propósito","no caminho","portanto","porém"]},{"q":"Marcadores de discurso deixam a fala:","ans":0,"ctx":"","exp":"Naturalidade.","opts":["mais natural e fluida","apenas mais formal","errada","mais curta"]}]$j$::jsonb where id = '32401970-0276-429c-928e-4a1f483e676c';
update licoes set titulo = 'Hedges e fillers na fala', sub = 'sort of / I mean / kind of', explicacao = 'Nativos suavizam e ganham tempo com: sort of / kind of (meio que), I mean (quer dizer), you know (sabe), like (tipo), or something (ou algo assim), more or less (mais ou menos). Em excesso soa inseguro; na medida, soa natural.', dica = '''Kind of'' suaviza: ''It''s kind of expensive'' = e meio caro.', exemplos = $j$[{"en":"It's kind of complicated.","pt":"É meio complicado."},{"en":"I mean, it could work.","pt":"Quer dizer, poderia funcionar."},{"en":"We need milk or something.","pt":"Precisamos de leite ou algo assim."}]$j$::jsonb, questoes = $j$[{"q":"'Kind of/sort of' =","ans":0,"ctx":"","exp":"Suavizador.","opts":["meio que (suaviza)","exatamente","nunca","muito formal"]},{"q":"'I mean' serve para:","ans":0,"ctx":"","exp":"Reformular.","opts":["reformular/explicar","ordenar","negar","perguntar"]},{"q":"'Or something' =","ans":0,"ctx":"","exp":"Imprecisão proposital.","opts":["ou algo do tipo","com certeza","nada","de novo"]},{"q":"Usar fillers em excesso soa:","ans":0,"ctx":"","exp":"Cuidado com o excesso.","opts":["inseguro","genial","formal","escrito"]},{"q":"'More or less' =","ans":0,"ctx":"","exp":"Aproximação.","opts":["mais ou menos","muito","pouco","exato"]},{"q":"Na medida certa, fillers deixam a fala:","ans":0,"ctx":"","exp":"Naturalidade.","opts":["mais natural","mais robótica","errada","formal demais"]}]$j$::jsonb where id = '106f5a4e-d98f-488d-bd81-ab3c27c1703b';
update licoes set titulo = 'Elipse na fala natural', sub = 'You coming? Been there.', explicacao = 'Nativos omitem palavras obvias (elipse). ''Are you coming?'' -> ''You coming?''. ''I have been there'' -> ''Been there''. ''Do you want some?'' -> ''Want some?''. Comum na fala informal, torna tudo mais ágil.', dica = 'Cai o auxiliar/sujeito quando o sentido continua claro.', exemplos = $j$[{"en":"You coming tonight?","pt":"Você vem hoje à noite?"},{"en":"Sounds good to me.","pt":"Parece bom pra mim."},{"en":"Told you so!","pt":"Eu te avisei!"}]$j$::jsonb, questoes = $j$[{"q":"'Are you ready?' vira (informal):","ans":0,"ctx":"","exp":"Cai o auxiliar.","opts":["You ready?","You is ready?","Ready you?","Are ready?"]},{"q":"'I have finished' vira:","ans":0,"ctx":"","exp":"Elipse do sujeito+aux.","opts":["Finished!","Have I finished","Finish me","I finish"]},{"q":"Elipse é comum em:","ans":0,"ctx":"","exp":"Informalidade.","opts":["fala informal","contratos","provas","leis"]},{"q":"'Do you want tea?' vira:","ans":0,"ctx":"","exp":"Cai 'do you'.","opts":["Want some tea?","You want is tea?","Tea you?","Want you tea?"]},{"q":"'Told you so' omite:","ans":0,"ctx":"","exp":"Omite o sujeito 'I'.","opts":["I","so","you","told"]},{"q":"A elipse deixa a fala:","ans":0,"ctx":"","exp":"Agilidade.","opts":["mais ágil/natural","mais longa","formal","escrita"]}]$j$::jsonb where id = '2cc6f21a-84fb-4c57-b442-77f8cbdee49a';
update licoes set titulo = 'Fronting para ênfase', sub = 'This I have to see', explicacao = 'Mover elementos para o inicio da frase da ênfase (fronting). ''This I have to see'' (isso eu preciso ver). ''Down came the rain''. ''Such was her joy that...''. Comum na escrita literária e na fala enfática.', dica = 'O objeto ou complemento vai para a frente para destacar.', exemplos = $j$[{"en":"That I don't believe.","pt":"Nisso eu não acredito."},{"en":"Down came the rain.","pt":"E a chuva desabou."},{"en":"Such was his fear that he ran.","pt":"Tamanho era seu medo que ele correu."}]$j$::jsonb, questoes = $j$[{"q":"Fronting serve para:","ans":0,"ctx":"","exp":"Ênfase.","opts":["dar ênfase","fazer pergunta","negar","pedir"]},{"q":"'I don't believe that' com fronting:","ans":0,"ctx":"","exp":"Objeto para frente.","opts":["That I don't believe.","That I believe don't.","Believe that I don't.","Don't that I believe."]},{"q":"'Such was...' é:","ans":0,"ctx":"","exp":"Estrutura enfática.","opts":["fronting enfático","erro","pergunta","condicional"]},{"q":"Fronting é mais comum em:","ans":0,"ctx":"","exp":"Estilo/ênfase.","opts":["escrita literária/fala enfática","e-mails de trabalho","listas","formulários"]},{"q":"'Down came the rain' destaca:","ans":0,"ctx":"","exp":"Efeito dramático.","opts":["a direção/imagem (down)","só o sujeito","o tempo","o lugar exato"]},{"q":"Fronting muda:","ans":0,"ctx":"","exp":"Só a ênfase.","opts":["a ênfase, não o sentido básico","o sentido totalmente","o tempo verbal","o número"]}]$j$::jsonb where id = '810407aa-c51e-48ef-b5ac-888fdb77e3f9';
update licoes set titulo = 'Subjuntivo em inglês II', sub = 'I suggest that he be...', explicacao = 'O subjuntivo (formal) usa o verbo na forma base após suggest, recommend, insist, demand, propose + that: ''I suggest that he BE present'' (não ''is''). Também em expressões fixas: ''God save the Queen'', ''Be that as it may''.', dica = 'Após ''suggest/insist that'', use o verbo sem conjugar: ''that she go'', ''that he be''.', exemplos = $j$[{"en":"I recommend that he see a doctor.","pt":"Recomendo que ele veja um medico."},{"en":"They insisted that she be present.","pt":"Insistiram que ela estivesse presente."},{"en":"Be that as it may, we proceed.","pt":"Seja como for, seguimos."}]$j$::jsonb, questoes = $j$[{"q":"Complete: I suggest that he ___ early.","ans":0,"ctx":"","exp":"Subjuntivo: forma base.","opts":["leave","leaves","left","is leaving"]},{"q":"Complete: They demand that she ___ here.","ans":0,"ctx":"","exp":"that she be (subjuntivo).","opts":["be","is","was","being"]},{"q":"O subjuntivo usa o verbo:","ans":0,"ctx":"","exp":"Forma base.","opts":["na forma base","sempre no passado","com -ing","com to"]},{"q":"Complete: I insist that he ___ the truth.","ans":0,"ctx":"","exp":"that he tell.","opts":["tell","tells","told","telling"]},{"q":"'Be that as it may' é:","ans":0,"ctx":"","exp":"Subjuntivo fossilizado.","opts":["expressão fixa (seja como for)","erro","pergunta","futuro"]},{"q":"O subjuntivo aparece muito em:","ans":0,"ctx":"","exp":"Registro formal.","opts":["inglês formal/americano","gírias","mensagens","música pop"]}]$j$::jsonb where id = '9527ad31-84b9-4021-b8b8-97a049ba9f9b';
update licoes set titulo = 'Inversão avançada', sub = 'No sooner had... than', explicacao = 'Estruturas enfáticas com inversão: ''No sooner had I arrived than it rained'', ''Hardly had she left when...'', ''Only after X did Y happen'', ''Not until... did...''. Muito formais e literárias.', dica = '''No sooner... than''; ''Hardly/Scarcely... when''.', exemplos = $j$[{"en":"No sooner had we sat down than he called.","pt":"Mal nos sentamos e ele ligou."},{"en":"Only then did I understand.","pt":"Só então eu entendi."},{"en":"Not until midnight did she sleep.","pt":"Só à meia-noite ela dormiu."}]$j$::jsonb, questoes = $j$[{"q":"Complete: No sooner had I left ___ it rained.","ans":0,"ctx":"","exp":"No sooner... than.","opts":["than","when","then","that"]},{"q":"Complete: Hardly had he arrived ___ she left.","ans":0,"ctx":"","exp":"Hardly... when.","opts":["when","than","then","that"]},{"q":"Complete: Only then ___ I realize.","ans":0,"ctx":"","exp":"Inversão: did + I.","opts":["did","I did","do","was"]},{"q":"Complete: Not until 6pm ___ he call.","ans":0,"ctx":"","exp":"did + sujeito.","opts":["did","he did","does","was"]},{"q":"Essas estruturas são:","ans":0,"ctx":"","exp":"Registro alto.","opts":["formais/literárias","gírias","erros","infantis"]},{"q":"'Scarcely had... when' descreve:","ans":0,"ctx":"","exp":"Sequência rápida.","opts":["dois eventos quase simultâneos","condição","futuro","opinião"]}]$j$::jsonb where id = 'fd465bfb-b5f6-4848-8285-a1ce0e66407e';
update licoes set titulo = 'Ênfase: the very / the only', sub = 'the very thing / the only one', explicacao = 'Para enfatizar: ''the very'' (exatamente esse - the very thing I needed), ''the only'' (o único), ''the sheer'' (puro/absoluto - the sheer size), ''own'' (próprio - my own room). Reforçam com elegância.', dica = '''The very'' = precisamente aquele; ''sheer'' = puro/total.', exemplos = $j$[{"en":"This is the very book I wanted.","pt":"Este e exatamente o livro que eu queria."},{"en":"The sheer scale amazed us.","pt":"A escala absoluta nos impressionou."},{"en":"I have my own reasons.","pt":"Tenho minhas próprias razões."}]$j$::jsonb, questoes = $j$[{"q":"'The very thing' =","ans":0,"ctx":"","exp":"Precisamente aquela.","opts":["exatamente a coisa","uma coisa qualquer","a coisa errada","quase a coisa"]},{"q":"'The sheer size' enfatiza:","ans":0,"ctx":"","exp":"sheer = puro/total.","opts":["o tamanho puro/absoluto","o tamanho pequeno","a cor","o preço"]},{"q":"'My own car' enfatiza:","ans":0,"ctx":"","exp":"own = próprio.","opts":["posse/exclusividade","aluguel","carro velho","carro dos outros"]},{"q":"'The only one' =","ans":0,"ctx":"","exp":"Exclusividade.","opts":["o único","um dos vários","o primeiro","o último"]},{"q":"'The very' vem antes de:","ans":0,"ctx":"","exp":"the very + substantivo.","opts":["um substantivo","um verbo","um advérbio","uma preposição"]},{"q":"Essas formas servem para:","ans":0,"ctx":"","exp":"Ênfase elegante.","opts":["reforçar com elegância","negar","perguntar","resumir"]}]$j$::jsonb where id = '304845eb-caf0-468e-8cc5-b3e1a05bf743';
update licoes set titulo = 'Nominalização (acadêmico)', sub = 'decide -> the decision to', explicacao = 'Textos acadêmicos preferem substantivos a verbos (nominalização). Em vez de ''They decided quickly'', escreve-se ''The quick decision...''. ''Prices increased'' -> ''The increase in prices''. Deixa o texto mais denso e impessoal.', dica = 'Transforme o verbo/ação em substantivo para soar acadêmico.', exemplos = $j$[{"en":"The failure of the plan surprised us.","pt":"O fracasso do plano nos surpreendeu."},{"en":"There was a sharp rise in costs.","pt":"Houve um aumento acentuado nos custos."},{"en":"Her analysis was thorough.","pt":"A análise dela foi minuciosa."}]$j$::jsonb, questoes = $j$[{"q":"'They decided' nominalizado:","ans":0,"ctx":"","exp":"verbo -> substantivo.","opts":["the decision","deciding fast","decide it","they decide"]},{"q":"'Prices rose' nominalizado:","ans":0,"ctx":"","exp":"the rise.","opts":["the rise in prices","prices rising up","rise prices","priced rise"]},{"q":"Nominalização deixa o texto:","ans":0,"ctx":"","exp":"Estilo acadêmico.","opts":["mais denso/impessoal","mais coloquial","mais curto sempre","errado"]},{"q":"'He analyzed the data' -> substantivo:","ans":0,"ctx":"","exp":"analysis.","opts":["his analysis of the data","he analyze","analyzing he","data analyze"]},{"q":"'They failed' -> substantivo:","ans":0,"ctx":"","exp":"failure.","opts":["their failure","failing them","fail it","they fail"]},{"q":"Nominalização é típica de:","ans":0,"ctx":"","exp":"Registro acadêmico.","opts":["escrita acadêmica/formal","conversa de bar","memes","SMS"]}]$j$::jsonb where id = '4810220c-2506-42a7-a04b-63dfcdac0116';
update licoes set titulo = 'Voz passiva para objetividade', sub = 'It was found that...', explicacao = 'Na escrita científica/formal, a passiva remove o agente e soa objetiva: ''The experiment was conducted'', ''It was found that...'', ''Data were collected''. Foca no processo, não em quem fez.', dica = 'Use passiva quando quem age não importa ou para soar impessoal.', exemplos = $j$[{"en":"The samples were analyzed carefully.","pt":"As amostras foram analisadas com cuidado."},{"en":"It was concluded that the drug works.","pt":"Concluiu-se que o remédio funciona."},{"en":"Mistakes were made.","pt":"Erros foram cometidos."}]$j$::jsonb, questoes = $j$[{"q":"'We conducted the test' na forma objetiva:","ans":0,"ctx":"","exp":"Passiva impessoal.","opts":["The test was conducted","We did test it","Test we conduct","Conducting test"]},{"q":"'It was found that' foca em:","ans":0,"ctx":"","exp":"Objetividade.","opts":["o resultado, não quem achou","a pessoa","o tempo","o lugar"]},{"q":"A passiva acadêmica remove:","ans":0,"ctx":"","exp":"Foco no processo.","opts":["o agente (quem faz)","o verbo","o objeto","o tempo"]},{"q":"'Data were collected' soa:","ans":0,"ctx":"","exp":"Registro científico.","opts":["objetivo/científico","informal","grosseiro","poético"]},{"q":"'Mistakes were made' evita:","ans":0,"ctx":"","exp":"Omite o agente.","opts":["apontar o culpado","o passado","o plural","o verbo"]},{"q":"Passiva é preferida quando:","ans":0,"ctx":"","exp":"Objetividade.","opts":["o agente é irrelevante/impessoal","queremos culpar alguém","é informal","há pressa"]}]$j$::jsonb where id = '0b718085-d3c5-438f-802b-2cb282a4546f';
update licoes set titulo = 'Conectores formais raros', sub = 'notwithstanding / hence / thereby', explicacao = 'Conectores de alto registro: notwithstanding (não obstante), hence/thus (portanto), thereby (assim/com isso), whereby (pelo qual), henceforth (de agora em diante), albeit (embora). Comuns em textos jurídicos/acadêmicos.', dica = '''Albeit'' = although, porém mais formal e curto: ''a small, albeit important, change''.', exemplos = $j$[{"en":"The plan, albeit risky, worked.","pt":"O plano, embora arriscado, funcionou."},{"en":"He was late; hence the delay.","pt":"Ele atrasou; daí o atraso."},{"en":"Notwithstanding the cost, we agreed.","pt":"Não obstante o custo, concordamos."}]$j$::jsonb, questoes = $j$[{"q":"'Albeit' significa:","ans":0,"ctx":"","exp":"= although (formal).","opts":["embora (formal)","portanto","além disso","por exemplo"]},{"q":"'Hence' =","ans":0,"ctx":"","exp":"Consequência.","opts":["portanto/daí","porém","depois","antes"]},{"q":"'Notwithstanding' =","ans":0,"ctx":"","exp":"Concessão formal.","opts":["não obstante/apesar de","por causa de","assim que","enquanto"]},{"q":"'Thereby' =","ans":0,"ctx":"","exp":"Meio/resultado.","opts":["assim/com isso","lá","quase","porém"]},{"q":"Esses conectores aparecem em:","ans":0,"ctx":"","exp":"Alto registro.","opts":["textos jurídicos/acadêmicos","conversa casual","memes","receitas"]},{"q":"'Henceforth' =","ans":0,"ctx":"","exp":"A partir de agora.","opts":["de agora em diante","no passado","porém","às vezes"]}]$j$::jsonb where id = 'c2e90d4f-99e2-4349-bc41-5fa330cc4b54';
update licoes set titulo = 'Comparações idiomáticas', sub = 'as good as gold', explicacao = 'Comparações fixas (similes): as good as gold (comportado), like a fish out of water (deslocado), as easy as pie (facílimo), like water off a duck''s back (não faz efeito), as stubborn as a mule (teimoso).', dica = 'São fixas: não troque as palavras (não ''as good as silver'').', exemplos = $j$[{"en":"The kids were as good as gold.","pt":"As crianças se comportaram muito bem."},{"en":"I felt like a fish out of water.","pt":"Me senti totalmente deslocado."},{"en":"It was as easy as pie.","pt":"Foi facílimo."}]$j$::jsonb, questoes = $j$[{"q":"'As good as gold' (sobre criança) =","ans":0,"ctx":"","exp":"Bem comportada.","opts":["muito comportada","rica","dourada","travessa"]},{"q":"'Like a fish out of water' =","ans":0,"ctx":"","exp":"Fora do ambiente.","opts":["deslocado/desconfortável","molhado","com fome","nadando bem"]},{"q":"'As easy as pie' =","ans":0,"ctx":"","exp":"Facílimo.","opts":["muito fácil","doce","difícil","gostoso"]},{"q":"'Like water off a duck's back' =","ans":0,"ctx":"","exp":"Não faz efeito.","opts":["não afeta a pessoa","molhado","rápido","sujo"]},{"q":"'As stubborn as a mule' =","ans":0,"ctx":"","exp":"Teimoso.","opts":["muito teimoso","forte","lento","burro literalmente"]},{"q":"Similes idiomáticos são:","ans":0,"ctx":"","exp":"Fixos.","opts":["expressões fixas","livres para trocar","erros","gramática"]}]$j$::jsonb where id = '243d75e5-04d8-45ec-9e00-9598b45cf4d0';
update licoes set titulo = 'Eufemismos', sub = 'passed away / let go', explicacao = 'Eufemismos suavizam temas delicados: passed away (faleceu), let go / made redundant (demitido), between jobs (desempregado), put to sleep (sacrificar animal), economical with the truth (mentir educadamente), senior (idoso).', dica = 'Servem para soar sensível: ''passed away'' é mais gentil que ''died''.', exemplos = $j$[{"en":"Her grandfather passed away last year.","pt":"O avô dela faleceu ano passado."},{"en":"He was let go last month.","pt":"Ele foi demitido mês passado."},{"en":"I'm between jobs right now.","pt":"Estou sem emprego no momento."}]$j$::jsonb, questoes = $j$[{"q":"'Passed away' =","ans":0,"ctx":"","exp":"Eufemismo de 'died'.","opts":["faleceu (suave)","viajou","passou","dormiu"]},{"q":"'Let go' (no trabalho) =","ans":0,"ctx":"","exp":"Demitido (suave).","opts":["demitido","promovido","de férias","contratado"]},{"q":"'Between jobs' =","ans":0,"ctx":"","exp":"Eufemismo.","opts":["desempregado (suave)","com dois empregos","ocupado","aposentado"]},{"q":"Eufemismos servem para:","ans":0,"ctx":"","exp":"Sensibilidade.","opts":["suavizar temas delicados","ofender","encurtar","confundir"]},{"q":"'Economical with the truth' =","ans":0,"ctx":"","exp":"Eufemismo para mentir.","opts":["mentir/omitir educadamente","ser honesto","economizar","falar demais"]},{"q":"'Senior citizen' é eufemismo para:","ans":0,"ctx":"","exp":"Idoso.","opts":["idoso","chefe","veterano","estudante"]}]$j$::jsonb where id = 'f6e8c37e-2045-435d-acd2-e292024ff8a0';
update licoes set titulo = 'Ironia e sarcasmo II', sub = 'Oh, great. Just what I needed.', explicacao = 'Ironia diz o oposto do sentido literal, sinalizada pelo tom/contexto: ''Oh, wonderful'' (após algo ruim), ''Just what I needed'' (sarcástico), ''Well, that went well'' (deu errado), ''Nice one'' (você errou). Entender ironia é chave no C2.', dica = 'O contexto revela: elogio + situação ruim = sarcasmo.', exemplos = $j$[{"en":"Oh great, the car won't start.","pt":"Ótimo, o carro não liga."},{"en":"Well, that went well.","pt":"Foi um sucesso... (irônico)."},{"en":"Nice one, you broke it.","pt":"Parabéns, você quebrou."}]$j$::jsonb, questoes = $j$[{"q":"'Oh, great' após um problema é:","ans":0,"ctx":"","exp":"Ironia.","opts":["sarcasmo","elogio real","pergunta","pedido"]},{"q":"Ironia diz:","ans":0,"ctx":"","exp":"Sentido invertido.","opts":["o oposto do literal","sempre a verdade","uma ordem","um número"]},{"q":"'Well, that went well' (após falha) =","ans":0,"ctx":"","exp":"Sarcasmo.","opts":["deu tudo errado","foi ótimo","vamos de novo","acabou bem"]},{"q":"O que sinaliza a ironia?","ans":0,"ctx":"","exp":"Tom/contexto.","opts":["tom e contexto","só a gramática","o plural","o tempo verbal"]},{"q":"'Nice one' (após um erro) =","ans":0,"ctx":"","exp":"Sarcástico.","opts":["crítica sarcástica","elogio sincero","agradecimento","dúvida"]},{"q":"Entender ironia exige:","ans":0,"ctx":"","exp":"Contexto.","opts":["ler o contexto","só o dicionário","sotaque perfeito","vocabulário formal"]}]$j$::jsonb where id = '1ff6d572-7bbb-4431-8d7e-308f3fdd2a06';
update licoes set titulo = 'Understatement e hipérbole', sub = 'not bad / a million times', explicacao = 'Understatement diminui (típico UK): ''not bad'' (= ótimo), ''a bit of a problem'' (= problemão), ''rather good''. Hipérbole exagera: ''I''ve told you a million times'', ''starving'', ''dying to see it''. Ambos são expressivos.', dica = 'Understatement suaviza; hipérbole exagera para efeito.', exemplos = $j$[{"en":"The food was not bad at all.","pt":"A comida estava ótima (understatement)."},{"en":"I'm starving!","pt":"Estou morrendo de fome!"},{"en":"I've said it a thousand times.","pt":"Já disse mil vezes."}]$j$::jsonb, questoes = $j$[{"q":"'Not bad' (understatement) =","ans":0,"ctx":"","exp":"Elogio suavizado.","opts":["bem bom","péssimo","normal","estranho"]},{"q":"'I'm starving' é:","ans":0,"ctx":"","exp":"Exagero.","opts":["hipérbole (exagero)","literal (morrendo)","understatement","ironia"]},{"q":"Understatement é típico do inglês:","ans":0,"ctx":"","exp":"Britânico.","opts":["britânico","técnico","antigo","jurídico"]},{"q":"'A bit of a problem' pode ser:","ans":0,"ctx":"","exp":"Understatement.","opts":["um problema sério","nada","uma dúvida","uma piada"]},{"q":"Hipérbole serve para:","ans":0,"ctx":"","exp":"Efeito enfático.","opts":["enfatizar exagerando","ser literal","suavizar","resumir"]},{"q":"'Dying to see it' =","ans":0,"ctx":"","exp":"Hipérbole.","opts":["muito ansioso (exagero)","literal morrer","com medo","sem interesse"]}]$j$::jsonb where id = '784559c9-0192-4db9-b25c-5b547884b581';
update licoes set titulo = 'Metáfora no dia a dia', sub = 'time is money', explicacao = 'Metáforas comuns tratam ideias abstratas como concretas: ''time is money'' (tempo é valioso), ''a flood of emails'' (muitos), ''the heart of the city'' (centro), ''grasp an idea'' (entender), ''a warm welcome''. Estão por toda parte no inglês.', dica = 'Não são literais: ''grasp an idea'' e entender, não segurar.', exemplos = $j$[{"en":"I got a flood of messages.","pt":"Recebi uma enxurrada de mensagens."},{"en":"She couldn't grasp the concept.","pt":"Ela não conseguiu captar o conceito."},{"en":"We live in the heart of the city.","pt":"Moramos no coração da cidade."}]$j$::jsonb, questoes = $j$[{"q":"'A flood of emails' =","ans":0,"ctx":"","exp":"Metáfora de quantidade.","opts":["muitos emails","emails molhados","poucos","só spam"]},{"q":"'Grasp an idea' =","ans":0,"ctx":"","exp":"Compreender.","opts":["entender","segurar","escrever","esquecer"]},{"q":"'The heart of the city' =","ans":0,"ctx":"","exp":"Centro.","opts":["o centro","o hospital","a periferia","o parque"]},{"q":"'Time is money' significa:","ans":0,"ctx":"","exp":"Valor do tempo.","opts":["tempo é valioso","dinheiro voa","trabalhe menos","seja rico"]},{"q":"Metáforas tratam o abstrato como:","ans":0,"ctx":"","exp":"Concreto.","opts":["algo concreto","números","verbos","erros"]},{"q":"'A warm welcome' é:","ans":0,"ctx":"","exp":"Figurado.","opts":["metáfora (acolhedor)","sobre temperatura","erro","literal"]}]$j$::jsonb where id = '3779d6a9-3fea-494c-bc13-601abb3a3087';
update licoes set titulo = 'Abreviações latinas', sub = 'e.g. / i.e. / etc.', explicacao = 'Do latim, comuns na escrita: e.g. (por exemplo - exempli gratia), i.e. (isto é/ou seja - id est), etc. (e assim por diante), vs. (versus), et al. (e outros), N.B. (nota bem/atenção).', dica = 'Cuidado: e.g. = por exemplo; i.e. = ou seja. Não são sinônimos!', exemplos = $j$[{"en":"Bring fruit, e.g. apples or pears.","pt":"Traga fruta, por exemplo macas ou peras."},{"en":"It's due Friday, i.e. in two days.","pt":"Vence sexta, ou seja, em dois dias."},{"en":"See Smith et al., 2020.","pt":"Ver Smith e outros, 2020."}]$j$::jsonb, questoes = $j$[{"q":"'e.g.' significa:","ans":0,"ctx":"","exp":"exempli gratia.","opts":["por exemplo","ou seja","e outros","versus"]},{"q":"'i.e.' significa:","ans":0,"ctx":"","exp":"id est.","opts":["ou seja/isto é","por exemplo","etc","nota"]},{"q":"'et al.' =","ans":0,"ctx":"","exp":"et alii.","opts":["e outros (autores)","e tudo","por exemplo","veja"]},{"q":"'etc.' =","ans":0,"ctx":"","exp":"et cetera.","opts":["e assim por diante","exatamente","porém","ou seja"]},{"q":"'e.g.' e 'i.e.' são:","ans":0,"ctx":"","exp":"Sentidos distintos.","opts":["diferentes","sinônimos","iguais","verbos"]},{"q":"'N.B.' pede:","ans":0,"ctx":"","exp":"nota bene.","opts":["atenção (note bem)","por exemplo","fim","versus"]}]$j$::jsonb where id = 'cdf56eda-7290-490f-91d2-d038a992b564';
update licoes set titulo = 'Contrações coloquiais', sub = 'gonna / wanna / gotta', explicacao = 'Na fala rápida, reduções: gonna (going to), wanna (want to), gotta (got to/have to), gimme (give me), lemme (let me), dunno (don''t know), kinda (kind of). Só na FALA/informal - nunca em texto formal.', dica = 'Entenda ao ouvir, mas não escreva ''gonna'' em e-mail profissional.', exemplos = $j$[{"en":"I'm gonna call her.","pt":"Vou ligar pra ela."},{"en":"I gotta go now.","pt":"Tenho que ir agora."},{"en":"I dunno what to say.","pt":"Não sei o que dizer."}]$j$::jsonb, questoes = $j$[{"q":"'Gonna' = ","ans":0,"ctx":"","exp":"going to.","opts":["going to","gone to","got to","want to"]},{"q":"'Wanna' =","ans":0,"ctx":"","exp":"want to.","opts":["want to","went to","won't","was to"]},{"q":"'Gotta' =","ans":0,"ctx":"","exp":"(have) got to.","opts":["got to / have to","go to","gonna","get it"]},{"q":"Essas formas são usadas:","ans":0,"ctx":"","exp":"Informal.","opts":["só na fala/informal","em contratos","em provas","em leis"]},{"q":"'Dunno' =","ans":0,"ctx":"","exp":"don't know.","opts":["don't know","do now","done","did know"]},{"q":"Em e-mail formal, deve-se:","ans":0,"ctx":"","exp":"Evitar no formal.","opts":["evitar essas contrações","usar sempre","usar às vezes","usar só no título"]}]$j$::jsonb where id = '85a3d974-f1c1-485a-9aa3-669643020809';
update licoes set titulo = 'Provérbios', sub = 'the early bird catches the worm', explicacao = 'Provérbios são sabedoria popular fixa: the early bird catches the worm (quem madruga), don''t count your chickens (não conte vitória antes), actions speak louder than words, better late than never, when in Rome (faça como os locais).', dica = 'Muitas vezes só se diz o começo: ''Well, when in Rome...''.', exemplos = $j$[{"en":"The early bird catches the worm.","pt":"Deus ajuda quem cedo madruga."},{"en":"Actions speak louder than words.","pt":"Atos valem mais que palavras."},{"en":"Better late than never.","pt":"Antes tarde do que nunca."}]$j$::jsonb, questoes = $j$[{"q":"'The early bird catches the worm' =","ans":0,"ctx":"","exp":"Vantagem de agir cedo.","opts":["quem se antecipa se da bem","pássaros comem cedo","acorde tarde","trabalhe menos"]},{"q":"'Actions speak louder than words' =","ans":0,"ctx":"","exp":"Atos > palavras.","opts":["atos valem mais que promessas","grite mais","fale menos","escreva tudo"]},{"q":"'Don't count your chickens...' avisa para:","ans":0,"ctx":"","exp":"Não antecipar vitória.","opts":["não comemorar cedo demais","contar animais","ter pressa","desistir"]},{"q":"'When in Rome...' sugere:","ans":0,"ctx":"","exp":"Faca como os locais.","opts":["adaptar-se aos costumes locais","viajar","aprender latim","ficar em casa"]},{"q":"Provérbios são:","ans":0,"ctx":"","exp":"Ditados populares.","opts":["frases fixas de sabedoria","gírias novas","erros","gramática"]},{"q":"'Better late than never' =","ans":0,"ctx":"","exp":"Melhor tarde que nunca.","opts":["antes tarde do que nunca","chegue cedo","nunca atrase","desista"]}]$j$::jsonb where id = '5b1086df-7577-475e-9b2a-a66cf0c6e275';
update licoes set titulo = 'Gíria x padrão (registro)', sub = 'mate / awesome / knackered', explicacao = 'Saber alternar registro é domínio pleno. Gíria: mate/buddy (amigo), awesome/brilliant (ótimo), knackered/beat (exausto), grand/bucks (dinheiro), cheers (obrigado/UK). Reconheça, mas escolha conforme o contexto formal ou casual.', dica = 'Gírias criam intimidade; em contexto profissional, volte ao padrão.', exemplos = $j$[{"en":"Thanks, mate!","pt":"Valeu, cara!"},{"en":"I'm absolutely knackered.","pt":"Estou exausto."},{"en":"That's brilliant news.","pt":"Que notícia ótima."}]$j$::jsonb, questoes = $j$[{"q":"'Mate' (UK) =","ans":0,"ctx":"","exp":"Amigo (informal).","opts":["amigo/cara","apenas colega de trabalho","chefe","inimigo"]},{"q":"'Knackered' =","ans":0,"ctx":"","exp":"Muito cansado.","opts":["exausto","faminto","feliz","bravo"]},{"q":"'Cheers' (UK informal) pode significar:","ans":0,"ctx":"","exp":"Valeu/saúde.","opts":["obrigado","adeus formal","desculpa","por favor"]},{"q":"Gírias servem para:","ans":0,"ctx":"","exp":"Contexto casual.","opts":["intimidade/informalidade","documentos","provas","leis"]},{"q":"Em contexto profissional, o ideal é:","ans":0,"ctx":"","exp":"Padrão no formal.","opts":["usar o registro padrão","usar só gírias","misturar sempre","não falar"]},{"q":"Dominar registro significa:","ans":0,"ctx":"","exp":"Flexibilidade de registro.","opts":["saber alternar formal e informal","só falar formal","só gírias","traduzir tudo"]}]$j$::jsonb where id = 'cb9c58c7-ad6f-4887-b33a-26d7afa39bd0';
commit;
